SELECT symbol, interval_code, open_time, closed, number_of_trades, volume, ingestion_source, close_transition_token IS NOT NULL AS has_token, created_at, updated_at FROM candle WHERE interval_code='1m' AND ((symbol='EGLDUSDT' AND open_time IN ('2026-10-11 20:59:00','2026-10-11 21:00:00','2026-10-11 22:42:00','2026-10-11 22:43:00')) OR (symbol='ACEUSDT' AND open_time IN ('2026-10-12 10:04:00','2026-10-12 10:05:00')) OR (symbol='SHIBUSDT' AND open_time='2026-10-12 07:15:00')) ORDER BY symbol, open_time